head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.mode = "I"; // 'I' : 전송전, T 전송후
scwin.gDepCd = js_dep_cd;
// 사이버정보분석팀일경우 팀코드가 시장마다 다르기 때문에 상위부서코드로 넣어준다. 20240510
if (scwin.gDepCd.substring(0, 2) === '5B') {
    scwin.gDepCd = '5B10';
}
scwin.gEmpNo = js_emp_no;
scwin.key_row = frame.opener.scwin.key_row;
$c.info.js_emp_no; // 담당자코드
$c.info.js_emp_nm; // 담당자명

scwin.time_no; // 부서위치
scwin.time_field; // 통보시각 or 접수시각

scwin.key_dep_cd; // 담당자선택시 부서코드
scwin.key_ld_mkt_tp_cd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // PanelToGroupBox(panel_1);
        await scwin.read();
        setTimeout("fn_init()", 1000); // 데이터 로딩시간이 있어 1초후 화면초기화 작업한다.
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10807.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    txb_ISUR_CD.hide();
    txb_NOTI_SEQ.hide();
    txb_MODE.hide();
    txb_EMP_NO.hide();
    txb_NOTI_DDTM.hide();
    txb_LD_MKT_TP_CD.hide();
    for (let i = 1; i < 3; i++) {
        $p.getComponentById("txb_ACPT_NO" + i).hide();
        $p.getComponentById("txb_DEP_CD" + i).hide();
        $p.getComponentById("txb_NOTI_EMP_NO" + i).hide();
        $p.getComponentById("txb_ACPT_EMP_NO" + i).hide();

        // 시장감시부일때만 '공시시각','반송사유' 를 보여주고 다른팀일때 보여주지 않는다.
        if (scwin.gDepCd !== '5B10') {
            if (i === 1) {
                label_15.hide();
                panel_1.style.height = 408;
                panel_2.style.height = 138;
                label_24.style.top = 394;
                // btn_Cancel.style.top = 382;

                btn_Delete.hide();
                btn_Transmit.hide();
            }
            $p.getComponentById("txb_DISCLS_DDTM" + i).hide();
            $p.getComponentById("txb_NOTI_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
            $p.getComponentById("txb_NOTI_DDTM" + i).style.backgroundColor = '#b9d4f7';
            $p.getComponentById("txb_ACPT_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
            $p.getComponentById("txb_REMK" + i).style.backgroundColor = '#b9d4f7';
        }
    }
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    let noti_ddtm = txb_NOTI_DDTM.getValue();
    if (noti_ddtm === '') {
        // 전송전 입력모드
        scwin.mode = 'I';
        scwin.setPage();
    } else {
        // 전송후 각담당자 입력모드
        scwin.mode = 'T';
        txb_INQDISCLS_REQ_CONTN.style.backgroundColor = '#b9d4f7';
        txb_INQDISCLS_REQ_CONTN.setReadOnly(true);
        txb_REMK.style.backgroundColor = '#b9d4f7';
        txb_REMK.setReadOnly(true);
        img_com_srch.setDisabled(true);
    }

    // 데티어가 없을시 데이터로우를 생성해줘야 한다.
    if (txb_COM_ABBRV.getValue() === '') {
        await scwin.setCode();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10807.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
        await $c.win.alert(msg);
        const fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10807.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description 「검색」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
