///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Master.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_Sub",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Sub=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Sub.insertRow();
};

/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    let noti_seq = '';
    let isur_cd = '';
    if (scwin.key_row !== '') {
        noti_seq = frame.opener.dts_Grid.getCellData(scwin.key_row, "NOTI_SEQ");
        isur_cd = frame.opener.dts_Grid.getCellData(scwin.key_row, "ISUR_CD");
    }
    url += "&NOTI_SEQ=" + noti_seq;
    url += "&ISUR_CD=" + isur_cd;
    url += "&SCREN_ID=" + 'ULDSTF10807.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&NOTI_SEQ=" + noti_seq;
    url += "&ISUR_CD=" + isur_cd;
    url += "&SCREN_ID=" + 'ULDSTF10807.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_Sub",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_Sub=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name afterExec
 * @description after Exec 처리
 * @param {*} isur_cd isur_cd
 * @param {*} ld_mkt_tp_cd ld_mkt_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.afterExec = async function(isur_cd, ld_mkt_tp_cd) {
    txb_LD_MKT_TP_CD.setValue(ld_mkt_tp_cd);
    url += "&ISUR_CD=" + isur_cd;
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    rdo_HALT_YN.setValue('');
};

