    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setPage
 * @description 이벤트에 따라서 화면 리드온리 및 입력필드를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setPage = function() {
    let halt_yn = rdo_HALT_YN.getValue();
    let noti_ddtm = txb_NOTI_DDTM.getValue();
    if (scwin.mode === 'I') {
        // 전송전 입력모드
        label_24.hide();

        // for(var i=1;i<=3;i++) {
        for (let i = 1; i < 3; i++) {
            if (halt_yn === 'N' && i > 1) {
                $p.getComponentById("txb_NOTI_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
                $p.getComponentById("txb_NOTI_DDTM" + i).style.backgroundColor = '#b9d4f7';
                $p.getComponentById("txb_ACPT_EMP_NM" + i).style.backgroundColor = '#b9d4f7';
                $p.getComponentById("txb_REMK" + i).style.backgroundColor = '#b9d4f7';
                $p.getComponentById("txb_DISCLS_DDTM" + i).style.backgroundColor = '#b9d4f7';
                $p.getComponentById("txb_NOTI_EMP_NM" + i).setValue('');
                $p.getComponentById("txb_NOTI_DDTM" + i).setValue('');
                $p.getComponentById("txb_DEP_CD" + i).setValue('');
            } else {
                $p.getComponentById("txb_NOTI_EMP_NM" + i).style.backgroundColor = '#FFFFFF';
                $p.getComponentById("txb_NOTI_DDTM" + i).style.backgroundColor = '#FFFFFF';
                $p.getComponentById("txb_ACPT_EMP_NM" + i).style.backgroundColor = '#FFFFFF';
                $p.getComponentById("txb_REMK" + i).style.backgroundColor = '#FFFFFF';
                $p.getComponentById("txb_DISCLS_DDTM" + i).style.backgroundColor = '#FFFFFF';

                // 부서코드 셋팅
                if (i === 2) {
                    $p.getComponentById("txb_DEP_CD" + i).setValue('2430');
                }
                // else if(i==3)  {

                // 상품관리팀 20130415 상품 관리팀 제외.

                // setObjectValue(eval("txb_DEP_CD"+i),'2B20');

                // }

            } // if

        } // for

    } else if (scwin.mode = 'T') {

    }
};

/**
 * @method
 * @name del
 * @description del 처리
 * @returns {void}
 * @hidden N
 */
scwin.del = function() {
    txb_EMP_NO.setValue(scwin.gEmpNo);
    let res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        gLastJob = "삭제";
        let url = "/OnlineNotice.do?method=deleteOnlineNotice" + "&SCREN_ID=" + 'ULDSTF10807.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Sub)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const flag = true;
    let isur_cd = "";
    let contn = "";
    let halt_yn = "";
    let remk = "";
    isur_cd = txb_ISUR_CD.getValue();
    contn = txb_INQDISCLS_REQ_CONTN.getValue();
    halt_yn = rdo_HALT_YN.getValue();
    remk = txb_REMK.getValue();
    if (isur_cd === '') {
        await $c.win.alert("회사를 선택해 주세요.");
        return false;
    }
    if (halt_yn === '') {
        await $c.win.alert("매매거래정지여부를 선택해주세요.");
        return false;
    }
    if (contn === '') {
        await $c.win.alert("내용을 입력해주세요.");
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_INQDISCLS_REQ_CONTN, 100, "내용")) {
        txb_INQDISCLS_REQ_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_REMK, 100, "비고")) {
        txb_REMK.focus();
        return false;
    }
    let no_array;
    if (rdo_HALT_YN.getValue() === 'Y') {
        no_array = new Array("1", "2");
    } else {
        no_array = new Array("1");
    }
    for (let i = 1; i <= no_array.length; i++) {
        if ($p.getComponentById("txb_NOTI_EMP_NM" + no_array[i - 1]).getValue() === '') {
            await $c.win.alert("통보자를 입력해주세요.");
            return false;
        }
        if ($p.getComponentById("txb_NOTI_DDTM" + no_array[i - 1]).getValue() === '') {
            await $c.win.alert("통보시각을 입력해주세요.");
            return false;
        }
    }
    return flag;
};

/**
 * @method
 * @name checkMaxLength
 * @description check Max Length 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength = async function(obj, size, lbl) {
    const overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name transmit
 * @description transmit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.transmit = async function() {
    let rtn = false;
    txb_EMP_NO.setValue(scwin.gEmpNo);
    let noti_seq = txb_NOTI_SEQ.getValue();
    if (noti_seq === '') {
        txb_MODE.setValue("TI");
    } else {
        txb_MODE.setValue("TU");
    }
    rtn = await scwin.checkForm();
    if (rtn) {
        let res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            txb_COM_ABBRV.setValue('');
            txb_DISCLS_DDTM1.setValue('');
            gLastJob = "저장";
            let url = "/OnlineNotice.do?method=saveTelNotice" + "&SCREN_ID=" + 'ULDSTF10807.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputSub=dts_Sub)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} row_num row_num
 * @returns {void}
 * @hidden N
 */
scwin.delete = function(row_num) {
    $p.getComponentById("txb_COM_ABBRV" + row_num).setValue("");
    $p.getComponentById("txb_INQDISCLS_REQ_CONTN" + row_num).setValue("");
    $p.getComponentById("rdo_ONLN_NOTI_YN" + row_num).setValue('');
    $p.getComponentById("txb_ISUR_CD" + row_num).setValue("");
    $p.getComponentById("txb_CHRG_NM" + row_num).setValue("");
};

/**
 * @method
 * @name openDiscls
 * @description open Discls 처리
 * @param {*} num num
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDiscls = async function(num) {
    fn_SetPar = scwin.setDiscls;
    link_num = num;
    if (scwin.gDepCd !== '5B10') {
        // alert("시장감시부에서만 공시연결할 수 있습니다.");
        return;
    }
    if ($p.getComponentById("txb_ACPT_EMP_NO" + num).getValue() !== '') {
        const options = {
            id: "ULDSTF30007",
            title: "공시선택",
            type: "browserPopup",
            width: "10px",
            height: "20px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF30007.gfm", options);
    } else {
        await $c.win.alert("접수자를 먼저 입력해주세요.");
    }
};

/**
 * @method
 * @name setDiscls
 * @description 공시팝업에서 공시선택시 값 셋팅.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setDiscls = function(arrPar) {
    // 공시팝업에서 공시선택시 값 셋팅.
    // alert("arrPar[0] : " + arrPar[0] + " : arrPar[1] : " + arrPar[1] + " :arrPar[2] : " + arrPar[2]);
    const acpt_no = arrPar[0];
    const discls_title = arrPar[1];
    let discls_date = arrPar[2];
    discls_date = discls_date.substring(0, 4) + "-" + discls_date.substring(4, 6) + "-" + discls_date.substring(6, 8) + " " + discls_date.substring(8, 10) + ":" + discls_date.substring(10, 12) + "(" + discls_title + ")";
    $p.getComponentById("txb_ACPT_NO" + link_num).setValue(acpt_no);
    $p.getComponentById("txb_DISCLS_DDTM" + link_num).setValue(discls_date);
};

/**
 * @method
 * @name personSearch_Rtn
 * @description person Search Rtn 처리
 * @param {*} emp_no emp_no
 * @param {*} emp_nm emp_nm
 * @returns {void}
 * @hidden N
 */
scwin.personSearch_Rtn = function(emp_no, emp_nm) {
    js_emp_no.setValue(emp_no);
    js_emp_nm.setValue(emp_nm);
};

/**
 * @method
 * @name openPerson
 * @description open Person 처리
 * @param {*} obj1 obj1
 * @param {*} obj2 obj2
 * @param {*} no no
 * @param {*} gubun gubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPerson = async function(obj1, obj2, no, gubun) {
    if (txb_ISUR_CD.getValue() === '') {
        await $c.win.alert("회사를 먼저 선택해주세요.");
        return;
    }
    if (rdo_HALT_YN.getValue() === '') {
        await $c.win.alert("매매거래정지여부를 먼저 선택해주세요.");
        return;
    }
    if (no > 1 && (rdo_HALT_YN.getValue() === 'N' && rdo_HALT_YN.getValue() !== '1')) {
        return;
    }
    scwin.js_emp_no = obj1;
    scwin.js_emp_nm = obj2;
    if (gubun === 'A') {
        scwin.key_dep_cd = $p.getComponentById("txb_DEP_CD" + no).getValue();
    } else {
        scwin.key_dep_cd = "5B10";
    }
    const options = {
        id: "ULDSTF10808",
        title: "담당자선택",
        type: "browserPopup",
        width: 360 + 5,
        height: 400 + 30,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclproc/ULDSTF10808.gfm", options);
};

/**
 * @method
 * @name inputTime
 * @description input Time 처리
 * @param {*} no no
 * @param {*} gubun gubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputTime = async function(no, gubun) {
    // gubun 'N' =  통보시각, 'A' =  접수시각
    scwin.time_no = no;
    scwin.time_field = gubun;
    if (no > 1 && (rdo_HALT_YN.getValue() === 'N' && rdo_HALT_YN.getValue() !== '1')) {
        return;
    }
    if (scwin.mode === 'I' && gubun === 'N') {
        // 전송전 입력모드
        const options = {
            id: "ULDSTF10809",
            title: "시간입력",
            type: "browserPopup",
            width: 360 + 5,
            height: "180px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclproc/ULDSTF10809.gfm", options);
    } else if (scwin.mode === 'T' && gubun === 'A') {
        if (scwin.gDepCd === $p.getComponentById("txb_DEP_CD" + no).getValue()) {
            const options = {
                id: "ULDSTF10809",
                title: "시간입력",
                type: "browserPopup",
                width: 360 + 5,
                height: "180px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/dsclproc/ULDSTF10809.gfm", options);
        }
    }
};
